CREATE DATABASE IF NOT EXISTS travelmate CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE travelmate;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,role ENUM('agent','traveller') NOT NULL);
CREATE TABLE IF NOT EXISTS trips (id INT AUTO_INCREMENT PRIMARY KEY,traveller_id INT NOT NULL,title VARCHAR(180) NOT NULL,destination VARCHAR(180) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status ENUM('Draft','Shared','Approved') NOT NULL DEFAULT 'Draft',estimated_total DECIMAL(10,2) NOT NULL DEFAULT 0,FOREIGN KEY(traveller_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS itinerary_days (id INT AUTO_INCREMENT PRIMARY KEY,trip_id INT NOT NULL,day_number INT NOT NULL,title VARCHAR(180) NOT NULL,description TEXT,FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE,UNIQUE KEY unique_day(trip_id,day_number));
CREATE TABLE IF NOT EXISTS activities (id INT AUTO_INCREMENT PRIMARY KEY,day_id INT NOT NULL,title VARCHAR(180) NOT NULL,location VARCHAR(180),notes TEXT,FOREIGN KEY(day_id) REFERENCES itinerary_days(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cost_items (id INT AUTO_INCREMENT PRIMARY KEY,trip_id INT NOT NULL,category VARCHAR(120) NOT NULL,amount DECIMAL(10,2) NOT NULL,FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE);
